// Start the shift with both depths packed into one value...
local upd = CMND_BTL_GET_RAND(1, 4);
local dwd = CMND_BTL_GET_RAND(1, 4);
CMND_BTL_ADD_FLOOR_ATTR("FL01", upd);
CMND_BTL_ADD_FLOOR_ATTR("FL02", dwd);
CMND_BTL_TRIGGER_FLOOR_EV(FLOOR_EVT_QUICKSAND, (dwd << 4) + upd);
// ... and on the next cycle, end it.
CMND_BTL_TRIGGER_FLOOR_EV(FLOOR_EVT_QUICKSAND, 0);

// Played once, the first time the tornadoes come out
if (!bTelop)
{
	CMND_BTL_TRIGGER_FLOOR_EV(FLOOR_EVT_APPEARCYCLONE, 0);
}
